// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time1, uint256 time2) public {
        // Bound timestamps to be far apart so the require(block.timestamp > pastBlockTime) can pass
        vm.assume(time1 < 1000000);
        vm.assume(time2 > time1 + 1000 && time2 < 2000000);

        // Simulate a block number that is a multiple of 15
        vm.roll(15);

        // First call to set pastBlockTime
        vm.warp(time1);
        vm.deal(address(this), 10 ether); // give caller 10 ether
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // Second call on a block number that is NOT a multiple of 15
        vm.roll(16);
        vm.warp(time2);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // After second call, the balance should still be 10 ether because the transfer only happens on multiples of 15
        assertTrue(address(c).balance > 0);
    }
}

